package com.personal.assistant.module.scheduler.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.scheduler.dto.SchedulerJobRequest;import com.personal.assistant.module.scheduler.entity.*;import com.personal.assistant.module.scheduler.service.SchedulerJobService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/scheduler/jobs") public class SchedulerJobController {private final SchedulerJobService service;public SchedulerJobController(SchedulerJobService s){service=s;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping public ApiResponse<List<SchedulerJob>> list(){return ApiResponse.success(service.list(uid()));}@PostMapping public ApiResponse<Long> create(@Valid @RequestBody SchedulerJobRequest r){return ApiResponse.success(service.create(uid(),r));}@PutMapping("/{id}")public ApiResponse<Void> update(@PathVariable Long id,@Valid @RequestBody SchedulerJobRequest r){service.update(uid(),id,r);return ApiResponse.success();}@PatchMapping("/{id}/enabled")public ApiResponse<Void> toggle(@PathVariable Long id,@RequestParam boolean enabled){service.toggle(uid(),id,enabled);return ApiResponse.success();}@GetMapping("/logs")public ApiResponse<List<SchedulerJobLog>> logs(@RequestParam(required=false)Long jobId){return ApiResponse.success(service.listLogs(uid(),jobId));}}